INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41211, 'Psalms 78:5', 'Psalms', 78, 5, 'ورکړ هغه د اسراییلو قوم ته خپل شریعت هغه ولس چې د یعقوب نسل دی زمونږ نیکونو ته یې وکړ حکم چې اولادونو ته ورزده کړي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_5.mp3', '', 1761754199, 1761754199),
(41212, 'Psalms 78:6', 'Psalms', 78, 6, 'ترڅو راتلونکی نسل زده کړي هغه هم هغه کوچنیان چې لا پیدا نه دي او په خپل وار سره بیان خپل اولادونو ته کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_6.mp3', '', 1761754199, 1761754199),
(41213, 'Psalms 78:7', 'Psalms', 78, 7, 'نو په دې توګه به هغوی هم توکل وکاندي خدای باندې او هېر به نه کړي کوم کارونه چې هغه کړي دي بلکې هغوی به اطاعت یې د حکمونو کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_7.mp3', '', 1761754199, 1761754199),
(41214, 'Psalms 78:8', 'Psalms', 78, 8, 'او دوی به نه وي سرکښان او نافرمانه خلک لکه د خپلو نیکه‌ګانو په شان د چا چې زړه ټینګ باور نه درلود خدای باندې او نه یې روح ؤ وفادار هغه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_8.mp3', '', 1761754199, 1761754199),
(41215, 'Psalms 78:9', 'Psalms', 78, 9, 'سره له دې چې وو سمبال افرایمیان په لیندو خو د جګړې په ورځ یې تېښته وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_9.mp3', '', 1761754199, 1761754199),
(41216, 'Psalms 78:10', 'Psalms', 78, 10, 'هغوی د خدای سره خپل لوظ باندې وفا ونه کړه هغوی انکار وکړ ویې نه منلو قانون د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_10.mp3', '', 1761754199, 1761754199),
(41217, 'Psalms 78:11', 'Psalms', 78, 11, 'هغوی دا هېر کړل چې هغه څه وکړل هغه معجزې چې خدای ښودلې وې هغوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_11.mp3', '', 1761754199, 1761754199),
(41218, 'Psalms 78:12', 'Psalms', 78, 12, 'په داسې حال کې چې نیکونو یې کتل خدای معجزې ښودلې د مصر ملک او د ‎صوعن سیمه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_12.mp3', '', 1761754199, 1761754199),
(41219, 'Psalms 78:13', 'Psalms', 78, 13, 'خدای په دریاب کې کړله جوړه لاره هغوی یې پورې ویستل اوبه یې سمې د دېوال په شانتې ودرولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_13.mp3', '', 1761754199, 1761754199),
(41220, 'Psalms 78:14', 'Psalms', 78, 14, 'د ورځې دوی ته لارښوونه یې په ورېځې کړله او ټوله شپه به یې د اور په رڼا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_14.mp3', '', 1761754199, 1761754199),
(41221, 'Psalms 78:15', 'Psalms', 78, 15, 'هغه به دښته کې ګټونه چول او ورکولې به یې اوبه هغوی ته داسې پرېمانه د بحرونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_15.mp3', '', 1761754199, 1761754199),
(41222, 'Psalms 78:16', 'Psalms', 78, 16, 'هغه ویالې جوړې کړې چې شي جاري له ګټ نه ویې بهولې اوبه لکه سیندونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_16.mp3', '', 1761754199, 1761754199),
(41223, 'Psalms 78:17', 'Psalms', 78, 17, 'خو دوی د خدای په وړاندې دوامداره ګناهونه کول دښته کې وکړه سرکښي یې خدای تعالی په وړاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_17.mp3', '', 1761754199, 1761754199),
(41224, 'Psalms 78:18', 'Psalms', 78, 18, 'هغوی قصدي په خدای کاوه ازمېښت د خپلې خوښې د خوړو چې یې غوښتنه کړله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_18.mp3', '', 1761754199, 1761754199),
(41225, 'Psalms 78:19', 'Psalms', 78, 19, 'دوی به د خدای په ضد خبرې کړلې ویل به هغوی: «ایا کولای شي خدای مونږ ته دسترخوان وغوړوي دښته کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_19.mp3', '', 1761754199, 1761754199),
(41226, 'Psalms 78:20', 'Psalms', 78, 20, 'دغه رښتیا دي چې خدای ګټ وواهه او د سېلاب په شان جاري شوې اوبه خو ایا دا هم شي کولای چې ډوډۍ راته تیاره کاندي؟ او هم ورکړي خپل قوم ته غوښه؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_20.mp3', '', 1761754199, 1761754199),
(41227, 'Psalms 78:21', 'Psalms', 78, 21, 'نو څښتن دوی باندې شو ډېر په قهر چې کله یې واورېدې د دوی خبرې او د یعقوب په خلاف بل شولو اور په اسراییلو باندې یې قهر په ډېرېدلو شولو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_21.mp3', '', 1761754199, 1761754199),
(41228, 'Psalms 78:22', 'Psalms', 78, 22, 'ځکه چې دوی په خدای ایمان نه درلود باور یې نه درلود چې هغوی ته به خلاصون ورکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_22.mp3', '', 1761754199, 1761754199),
(41229, 'Psalms 78:23', 'Psalms', 78, 23, 'خو پاس اسمان ته هغه حکم وکړ او دروازې یې د اسمان پرانیستې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_23.mp3', '', 1761754199, 1761754199),
(41230, 'Psalms 78:24', 'Psalms', 78, 24, 'ورته ویې لېږلو من چې دوی یې وخوري او ویې بخښلې دوی ته د اسمان غلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_24.mp3', '', 1761754199, 1761754199),
(41231, 'Psalms 78:25', 'Psalms', 78, 25, 'انسان وخوړه ډوډۍ د فرښتو څومره چې دوی غوښته خدای ورکړه ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_25.mp3', '', 1761754199, 1761754199),
(41232, 'Psalms 78:26', 'Psalms', 78, 26, 'له ختیځه یې راوالوزاوه باد په اسمانو کې او په خپل قدرت یې راوړ باد له جنوبه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_26.mp3', '', 1761754199, 1761754199),
(41233, 'Psalms 78:27', 'Psalms', 78, 27, 'لکه د دوړو په څېر غوښه یې نازله کړله مرغان ډېر زیات لکه د شګو د دریاب د غاړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_27.mp3', '', 1761754199, 1761754199),
(41234, 'Psalms 78:28', 'Psalms', 78, 28, 'هغوی یې پرېښودل چې ولویږي د کمپ په منځ کې ټولو خېمو په شاوخوا باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_28.mp3', '', 1761754199, 1761754199),
(41235, 'Psalms 78:29', 'Psalms', 78, 29, 'نو خلکو وخوړل او شول پرې ماړه څه چې دوی غوښتي وو خدای ورکړل ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_29.mp3', '', 1761754199, 1761754199),
(41236, 'Psalms 78:30', 'Psalms', 78, 30, 'لا پوره شوې اشتها یې نه وه مړۍ د خولو یې لا خوړلې نه وه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_30.mp3', '', 1761754199, 1761754199),
(41237, 'Psalms 78:31', 'Psalms', 78, 31, 'چې شو راپورته د خدای قهر په دوی ویې وژل د دوی قوي سړي او کړل یې مړه د اسراییلو ځوانان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_31.mp3', '', 1761754199, 1761754199),
(41238, 'Psalms 78:32', 'Psalms', 78, 32, 'سره له دې ټولو کارو خلکو بس نه کړه ګناه سره له دې چې معجزې یې د هغه ولیدې خو دوی بیاهم ایمان رانه وړلو هغه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_32.mp3', '', 1761754199, 1761754199),
(41239, 'Psalms 78:33', 'Psalms', 78, 33, 'نو د هغوی ورځې یې کړې ختمې خوشې کړل یې کلونه خلاص په وېره وېره د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_33.mp3', '', 1761754199, 1761754199),
(41240, 'Psalms 78:34', 'Psalms', 78, 34, 'کله چې دوی نه به خدای ووژل ځینې کسان هغه ته وبه کړه رجوع د هغو پاتې خلکو هغوی توبه ویستله او سخته دعا یې کوله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_34.mp3', '', 1761754199, 1761754199),
(41241, 'Psalms 78:35', 'Psalms', 78, 35, 'دوی ته وریاد شول چې خدای ؤ ساتونکی د دوی چې خدای تعالی دی خلاصوونکی د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_35.mp3', '', 1761754199, 1761754199),
(41242, 'Psalms 78:36', 'Psalms', 78, 36, 'خو بیا به دوی کړه چاپلوسي په خپلو خولو هغه ته ویل به یې دروغ ورته په خپلو ژبو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_36.mp3', '', 1761754199, 1761754199),
(41243, 'Psalms 78:37', 'Psalms', 78, 37, 'هغه ته نه وو وفادار یې زړونه نه وو رښتیني د هغه لوظ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_37.mp3', '', 1761754199, 1761754199),
(41244, 'Psalms 78:38', 'Psalms', 78, 38, 'خو مهربان ؤ خدای خپل قوم باندې هغه ګناه د دوی وروبخښله او تباه یې نه کړل هغوی په څو څو وار یې د خپل قهر مخه ونیوله خپل غضب ټول یې راونه پاراوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_38.mp3', '', 1761754199, 1761754199),
(41245, 'Psalms 78:39', 'Psalms', 78, 39, 'هغه رایاد کړل چې هغوی دي صرف فاني انسانان لکه د باد په شان چې لګي بېرته نه راګرځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_39.mp3', '', 1761754199, 1761754199),
(41246, 'Psalms 78:40', 'Psalms', 78, 40, 'هغوی په دښته کې څو څو ځلې د هغه مقابل کې سرکښي وکړه په څو څو وار یې په صحرا کې خفه کړی هغه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_40.mp3', '', 1761754199, 1761754199),
(41247, 'Psalms 78:41', 'Psalms', 78, 41, 'هغوی بیا بیا په خدای کاوه ازمېښت سپېڅلی خدای د اسراییلو یې په تکلیف کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_41.mp3', '', 1761754199, 1761754199),
(41248, 'Psalms 78:42', 'Psalms', 78, 42, 'دوی کړلو هېر لوی قدرت د هغه او هغه ورځ چې دوی یې خلاص له دښمنانو کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_42.mp3', '', 1761754199, 1761754199),
(41249, 'Psalms 78:43', 'Psalms', 78, 43, 'هغوی کړې هېرې معجزې چې ښکاره کړې وې خدای مصر کې د صوعن سیمه کې عجیب کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_43.mp3', '', 1761754199, 1761754199),
(41250, 'Psalms 78:44', 'Psalms', 78, 44, 'کړې یې بدلې د سیندونو او نهرونو اوبه په وینو باندې د څښاک اوبه نه وې مصریانو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_44.mp3', '', 1761754199, 1761754199),
(41251, 'Psalms 78:45', 'Psalms', 78, 45, 'په هغو باندې یې نازل کړل مچان کړل په عذاب یې هغوی او هم چونګښې چې یې ویجاړه کړله خاوره د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_45.mp3', '', 1761754199, 1761754199),
(41252, 'Psalms 78:46', 'Psalms', 78, 46, 'هغه نازل کړل ملخان ورباندې چې یې فصلونه وخوري او چې تباه کړي کروندې د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_46.mp3', '', 1761754199, 1761754199),
(41253, 'Psalms 78:47', 'Psalms', 78, 47, 'د دوی تاکونه یې په ږلۍ تباه کړل د انځر ونې ورته ووهلې یخ باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_47.mp3', '', 1761754199, 1761754199),
(41254, 'Psalms 78:48', 'Psalms', 78, 48, 'د دوی پادې یې ووهلې په ږلۍ باندې او ووهلې یې په تندر رمې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_48.mp3', '', 1761754199, 1761754199),
(41255, 'Psalms 78:49', 'Psalms', 78, 49, 'اور د خپل قهر یې راواستولو ورته کړ یې نازل په هغوی غضب، قهر او مصیبت لکه د مرګ د فرښتو په شان په دوی راغلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_49.mp3', '', 1761754199, 1761754199),
(41256, 'Psalms 78:50', 'Psalms', 78, 50, 'هغه خاموش نه کړلو خپل قهر او نه یې وژغورلو ژوند د هغوی بلکې وبا باندې اخته کړل هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_50.mp3', '', 1761754199, 1761754199),
(41257, 'Psalms 78:51', 'Psalms', 78, 51, 'ټول یې کړل مړه د مصریانو مشران زامن د حام خېمو کې د هغوی د نارینتوب لومړنۍ مېوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_51.mp3', '', 1761754199, 1761754199),
(41258, 'Psalms 78:52', 'Psalms', 78, 52, 'بیا هغه خپل خلک راوویستل لکه پسونو په شان دښته کې وکړه لارښوونه یې د رمې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_52.mp3', '', 1761754199, 1761754199),
(41259, 'Psalms 78:53', 'Psalms', 78, 53, 'روغ او رمټ یې هغوی بوتلل او دوی نه وېرېدل خو دریاب ‎غرق کړل دښمنان د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_53.mp3', '', 1761754199, 1761754199),
(41260, 'Psalms 78:54', 'Psalms', 78, 54, 'خدای هغوی خپل پاک وطن ته راوستل هغه غره ته چې نیولی یې په خپل ښي لاس ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_54.mp3', '', 1761754199, 1761754199),
(41261, 'Psalms 78:55', 'Psalms', 78, 55, 'د دوی په مخکې یې وشړل د هغه ځای قومونه د هغوی ځمکه یې کړه تقسیم د اسراییلو قبیلو باندې کړلو مېشته یې خپل ولس بیا د هغوی کورو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_55.mp3', '', 1761754199, 1761754199),
(41262, 'Psalms 78:56', 'Psalms', 78, 56, 'خو سرکښي یې وکړه د خدای تعالی په وړاندې هغه یې وازمایلو قبول یې نه کړل د هغه حکمونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_56.mp3', '', 1761754199, 1761754199),
(41263, 'Psalms 78:57', 'Psalms', 78, 57, 'دوی یاغیان او بې‌وفا وو د نیکونو په شان بې‌اعتباره وو هغوی کږې لیندې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_57.mp3', '', 1761754199, 1761754199),
(41264, 'Psalms 78:58', 'Psalms', 78, 58, 'خدای یې په قهر کړ خپلو کفري عبادتګاوو جوړولو باندې خپلو بتانو عبادت باندې یې وپاراوه غیرت د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_58.mp3', '', 1761754199, 1761754199),
